import{_ as t,a,o as s,a6 as d}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"CMS Pages — Mass Delete","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-cms-pages-mass-delete","title":"Mass Delete CMS Pages","description":"Bulk-delete CMS pages. Non-existent IDs are silently skipped.","query":"mutation MassDeleteCmsPages($input: createAdminCmsPageMassDeleteInput!) {\\n  createAdminCmsPageMassDelete(input: $input) {\\n    adminCmsPageMassDelete {\\n      id\\n      deleted\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": { \\"indices\\": [12, 18] }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminCmsPageMassDelete\\": {\\n      \\"adminCmsPageMassDelete\\": {\\n        \\"id\\": \\"/api/admin/cms_page_mass_deletes/1\\",\\n        \\"deleted\\": [12, 18],\\n        \\"message\\": \\"CMS pages deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/cms/pages/mutations/mass-delete.md","filePath":"api/graphql-api/admin/cms/pages/mutations/mass-delete.md","lastUpdated":1787725411000}'),r={name:"api/graphql-api/admin/cms/pages/mutations/mass-delete.md"};function n(i,e,o,l,p,m){return s(),a("div",null,e[0]||(e[0]=[d('<h1 id="cms-pages-—-mass-delete" tabindex="-1">CMS Pages — Mass Delete <a class="header-anchor" href="#cms-pages-—-mass-delete" aria-label="Permalink to &quot;CMS Pages — Mass Delete&quot;">​</a></h1><p>Equivalent to <a href="/api/rest-api/admin/cms/pages-mass-delete.html"><code>POST /api/admin/cms/pages/mass-delete</code></a>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>createAdminCmsPageMassDelete</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>indices</code></td><td><code>[Int!]!</code></td><td>yes</td><td>CMS page IDs to delete. Must be non-empty.</td></tr></tbody></table><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><p>Bulk-deletes every page in <code>indices</code> in one call. <strong>Non-existent IDs are silently skipped</strong> — the operation does not fail the whole batch for a missing id. The response&#39;s <code>deleted</code> array lists the IDs actually removed; <code>message</code> is a human-readable summary. Each removed page also has its storefront redirects (url rewrites) cleaned up.</p><p><code>deleted</code> is returned as a <strong>plain array of IDs</strong> over GraphQL.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td><code>indices</code> empty or missing</td><td>validation error</td></tr><tr><td>Admin role lacks <code>cms.delete</code></td><td>permission error</td></tr></tbody></table>',11)]))}const u=t(r,[["render",n]]);export{h as __pageData,u as default};
